def correct_bracketing(brackets: str):
    # Validate the input string to ensure it only contains '<' and '>' characters
    if set(brackets) != {'<', '>'}:
        return False

    # Count the number of '<' and '>' characters in the input string
    count_open = brackets.count('<')
    count_close = brackets.count('>')

    # Check if the number of '<' characters is equal to the number of '>' characters
    if count_open != count_close:
        return False

    # Iterate through the input string and check if each '<' character has a matching '>' character
    stack = []
    for char in brackets:
        if char == '<':
            stack.append(char)
        elif char == '>':
            if not stack:
                return False
            stack.pop()

    # Return True if all conditions are met, otherwise return False
    return len(stack) == 0

